CREATE TABLE credentials(actor TEXT PRIMARY KEY REFERENCES users(actor), username TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE activation_tokens(digest TEXT PRIMARY KEY, actor TEXT NOT NULL REFERENCES users(actor), username TEXT NOT NULL COLLATE NOCASE, expires_at TEXT NOT NULL, consumed_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX activation_actor ON activation_tokens(actor);
CREATE TABLE auth_attempts(key TEXT PRIMARY KEY, count INTEGER NOT NULL, window_start INTEGER NOT NULL, locked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE audit_chain(seq INTEGER PRIMARY KEY AUTOINCREMENT, record_id TEXT NOT NULL UNIQUE, previous_hash TEXT NOT NULL, digest TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE runtime_metrics(key TEXT PRIMARY KEY, value INTEGER NOT NULL DEFAULT 0);
CREATE INDEX audit_created_id ON audit(created_at,id);
CREATE INDEX reports_period_status ON reports(month,status,current);
CREATE INDEX bills_due_status ON bills(status,json_extract(data,'$.dueOn'));
CREATE INDEX support_ticket_assignee ON supportTickets(json_extract(data,'$.assignee'),status);
CREATE INDEX support_chat_assignee ON supportChats(json_extract(data,'$.assignee'),status);
